//! Tests every function of [`ObjectProperties`] (`serialise`, `object_id`, `from_object`) for every struct that implements it,
//! along with [`GDObject::from_config`], which is built on top of the trait.
//!
//! Each implementor gets a module generated by [`object_properties_suite`] with the same set of tests.
//! The samples of each implementor deliberately use non-default values and cover every enum variant / optional field.
use std::fmt::Debug;

use super::{CONFIG_PROPERTY_IDS, test_config};
use crate::cclocallevels::{
    gdlevel::GDLevel,
    gdobj::{
        GDObject, ObjectProperties,
        constructors::{RotationConfig, SpinningObject, SpinningObjectConfig},
        gameplay::*,
        ids::{objects::*, properties as p},
        meta::GDObjConfig,
        structs::*,
        triggers::*,
    },
    properties::{PROPERTY_TABLE, get_obj_property_type},
};

/// Object IDs that no implementor of `ObjectProperties` uses.
const FOREIGN_OBJECT_IDS: [i32; 3] = [1, 0, -1];

fn direct<T: PartialEq + Debug>(actual: &T, expected: &T) {
    assert_eq!(actual, expected);
}

fn debug_repr<T: Debug>(actual: &T, expected: &T) {
    assert_eq!(format!("{actual:?}"), format!("{expected:?}"));
}

/// Builds the object inside a level, serialises the whole level, parses it again and returns the first object.
fn through_level(obj: GDObject) -> GDObject {
    let mut level = GDLevel::default();
    level.add_object(obj);
    let parsed = GDLevel::from_plist_string(level.serialise_to_string()).unwrap();
    parsed.get_decrypted_data().unwrap().objects.remove(0)
}

macro_rules! object_properties_suite {
    ($name:ident: $ty:ty {
        ids: [$($id:expr),+ $(,)?],
        samples: $samples:expr,
        compare: $cmp:expr $(,)?
    }) => {
        mod $name {
            use super::*;

            fn samples() -> Vec<$ty> {
                $samples
            }

            fn compare(actual: &$ty, expected: &$ty) {
                let cmp: fn(&$ty, &$ty) = $cmp;
                cmp(actual, expected)
            }

            const IDS: &[i32] = &[$($id),+];

            #[test]
            fn object_id() {
                for (s, s2) in samples().into_iter().zip(samples()) {
                    let id = s.object_id();
                    assert!(IDS.contains(&id), "unexpected object id {id}");
                    assert_eq!(GDObject::from_config(&test_config(), s2).id, id);
                }
            }

            #[test]
            fn serialise_has_no_duplicate_properties() {
                for s in samples() {
                    let mut ids = s.serialise().into_iter().map(|(id, _)| id).collect::<Vec<_>>();
                    let len = ids.len();
                    ids.sort();
                    ids.dedup();
                    assert_eq!(ids.len(), len, "duplicate properties in {:?}", s.serialise());
                }
            }

            #[test]
            fn serialise_has_no_config_properties() {
                for s in samples() {
                    for (id, v) in s.serialise() {
                        assert!(
                            !CONFIG_PROPERTY_IDS.contains(&id),
                            "property {id} = {v:?} belongs to GDObjConfig"
                        );
                    }
                }
            }

            #[test]
            fn serialised_values_match_property_table() {
                // every value must come back as the same `GDValue` variant when the object string is parsed.
                // 155 and kA properties are opaque and are not read back by `from_object`.
                for s in samples() {
                    for (id, v) in s.serialise() {
                        if id == 155 || id >= 10_000 {
                            continue;
                        }
                        let t = get_obj_property_type(id).unwrap_or(GDObjPropType::Unknown);
                        let name = PROPERTY_TABLE.get(&id).map(|e| e.0).unwrap_or("not in table");
                        assert_eq!(
                            GDValue::from(t, &v.to_string()),
                            v,
                            "property {id} ({name}) is written as {v:?} but parsed as {t:?}"
                        );
                    }
                }
            }

            #[test]
            fn from_config_properties_are_retrievable() {
                for (s, s2) in samples().into_iter().zip(samples()) {
                    let expected = s2.serialise();
                    let obj = GDObject::from_config(&test_config(), s);
                    for (id, v) in expected {
                        if CONFIG_PROPERTY_IDS.contains(&id) {
                            continue;
                        }
                        assert!(obj.has_property(id), "property {id} missing");
                        assert_eq!(obj.get_property(id), Some(v), "property {id}");
                    }
                }
            }

            #[test]
            fn from_config_keeps_config() {
                for s in samples() {
                    let obj = GDObject::from_config(&test_config(), s);
                    assert_eq!(obj.config, test_config());
                }
            }

            #[test]
            fn from_object_rejects_other_object_ids() {
                for s in samples() {
                    for id in FOREIGN_OBJECT_IDS {
                        let obj = GDObject::new(id, &test_config(), s.serialise());
                        assert!(<$ty as ObjectProperties>::from_object(&obj).is_none(), "object id {id}");
                    }
                }
            }

            #[test]
            fn from_object_accepts_object_without_properties() {
                for id in IDS {
                    let obj = GDObject::new(*id, &GDObjConfig::default(), vec![]);
                    assert!(<$ty as ObjectProperties>::from_object(&obj).is_some(), "object id {id}");
                }
            }

            #[test]
            fn from_object_after_from_config() {
                for (s, expected) in samples().into_iter().zip(samples()) {
                    let obj = GDObject::from_config(&test_config(), s);
                    let actual = <$ty as ObjectProperties>::from_object(&obj)
                        .unwrap_or_else(|| panic!("from_object returned None for {obj:?}"));
                    compare(&actual, &expected);
                }
            }

            #[test]
            fn from_object_after_object_string() {
                for (s, expected) in samples().into_iter().zip(samples()) {
                    let raw = GDObject::from_config(&test_config(), s).serialise_to_string();
                    let obj = GDObject::parse_str(&raw);
                    let actual = <$ty as ObjectProperties>::from_object(&obj)
                        .unwrap_or_else(|| panic!("from_object returned None for {raw}"));
                    compare(&actual, &expected);
                }
            }

            #[test]
            fn from_object_after_level_roundtrip() {
                for (s, expected) in samples().into_iter().zip(samples()) {
                    let obj = through_level(GDObject::from_config(&test_config(), s));
                    let actual = <$ty as ObjectProperties>::from_object(&obj)
                        .unwrap_or_else(|| panic!("from_object returned None for {obj:?}"));
                    compare(&actual, &expected);
                }
            }

            #[test]
            fn serialise_is_unchanged_after_object_string_roundtrip() {
                for (s, expected) in samples().into_iter().zip(samples()) {
                    let raw = GDObject::from_config(&test_config(), s).serialise_to_string();
                    if let Some(actual) = <$ty as ObjectProperties>::from_object(&GDObject::parse_str(&raw)) {
                        assert_eq!(actual.serialise(), expected.serialise());
                    }
                }
            }
        }
    };
}

