fn compare_pulse(actual: &PulseTrigger, expected: &PulseTrigger) {
    assert_eq!(
        actual.pulse_fade_in_time, expected.pulse_fade_in_time,
        "pulse_fade_in_time"
    );
    assert_eq!(
        actual.pulse_hold_time, expected.pulse_hold_time,
        "pulse_hold_time"
    );
    assert_eq!(
        actual.pulse_fade_out_time, expected.pulse_fade_out_time,
        "pulse_fade_out_time"
    );
    assert_eq!(
        actual.exclusive_pulse, expected.exclusive_pulse,
        "exclusive_pulse"
    );
    assert_eq!(actual.pulse_target, expected.pulse_target, "pulse_target");
    match (&actual.pulse_mode, &expected.pulse_mode) {
        (PulseMode::Colour(a), PulseMode::Colour(e)) => assert_eq!(a, e, "pulse_mode"),
        (PulseMode::HSV(a), PulseMode::HSV(e)) => assert_eq!(a, e, "pulse_mode"),
        _ => panic!("pulse_mode variant differs"),
    }
}

