fn compare_item_compare(actual: &ItemCompareTrigger, expected: &ItemCompareTrigger) {
    assert_eq!(actual.true_id, expected.true_id, "true_id");
    assert_eq!(actual.false_id, expected.false_id, "false_id");
    assert_eq!(actual.lhs, expected.lhs, "lhs");
    assert_eq!(actual.rhs, expected.rhs, "rhs");
    assert_eq!(actual.compare_op, expected.compare_op, "compare_op");
    assert_eq!(actual.tolerance, expected.tolerance, "tolerance");
}

