fn compare_orb(actual: &GDOrb, expected: &GDOrb) {
    assert_eq!(actual.otype, expected.otype, "otype");
    assert_eq!(
        actual.multi_activate, expected.multi_activate,
        "multi_activate"
    );
    assert_eq!(
        actual.no_plat_multi_activate, expected.no_plat_multi_activate,
        "no_plat_multi_activate"
    );
    assert_eq!(
        actual.extra_orb_config, expected.extra_orb_config,
        "extra_orb_config"
    );
}

