// ---------------- implementor-specific behaviour ----------------

/// `object_descriptor!` structs derive `Default`, so an object without any properties must parse to `Default::default()`.
macro_rules! bare_object_is_default {
    ($($name:ident: $ty:ty),* $(,)?) => {$(
        #[test]
        fn $name() {
            let obj = GDObject::new(<$ty>::default().object_id(), &GDObjConfig::default(), vec![]);
            assert_eq!(<$ty>::from_object(&obj), Some(<$ty>::default()));
        }
    )*};
}

bare_object_is_default! {
    bare_stop_trigger: StopTrigger,
    bare_alpha_trigger: AlphaTrigger,
    bare_toggle_trigger: ToggleTrigger,
    bare_link_visible_trigger: LinkVisibleTrigger,
    bare_timewarp_trigger: TimewarpTrigger,
    bare_group_reset_trigger: GroupResetTrigger,
    bare_shake_trigger: ShakeTrigger,
    bare_bg_speed_trigger: BGSpeedTrigger,
    bare_mg_speed_trigger: MGSpeedTrigger,
    bare_player_control_trigger: PlayerControlTrigger,
    bare_end_trigger: EndTrigger,
    bare_persistent_item_trigger: PersistentItemTrigger,
    bare_random_trigger: RandomTrigger,
    bare_spawn_trigger: SpawnTrigger,
    bare_on_death_trigger: OnDeathTrigger,
    bare_collision_block: CollisionBlock,
    bare_toggle_block: ToggleBlock,
    bare_state_block: StateBlock,
    bare_collision_trigger: CollisionTrigger,
    bare_instant_coll_trigger: InstantCollTrigger,
    bare_time_trigger: TimeTrigger,
    bare_time_control_trigger: TimeControlTrigger,
    bare_time_event_trigger: TimeEventTrigger,
    bare_camera_guide: CameraGuide,
    bare_follow_trigger: FollowTrigger,
    bare_animate_trigger: AnimateTrigger,
    bare_count_trigger: CountTrigger,
    bare_advanced_random_trigger: AdvancedRandomTrigger,
    bare_ui_config_trigger: UIConfigTrigger,
    bare_follow_player_y_trigger: FollowPlayerYTrigger,
    bare_event_trigger: EventTrigger,
    bare_middle_ground_trigger: MiddleGroundTrigger,
    bare_touch_trigger: TouchTrigger,
    bare_area_stop_trigger: AreaStopTrigger,
    bare_bpm_guide: BPMGuide,
    bare_rotate_gameplay_trigger: RotateGameplayTrigger,
    bare_pickup_trigger: PickupTrigger,
    bare_instant_count_trigger: InstantCountTrigger,
}

#[test]
fn end_trigger_from_object() {
    let obj = GDObject::parse_str("1,3600,2,2925,3,795,36,1,51,321,461,1,487,1;");
    assert_eq!(
        EndTrigger::from_object(&obj).unwrap(),
        EndTrigger {
            spawn_id: Some(321),
            target_pos: None,
            no_effects: false,
            instant: true,
            no_sfx: true
        }
    );
}

#[test]
fn advanced_random_from_real_object() {
    let obj = GDObject::parse_str("1,2068,2,75,3,75,155,1,11,1,87,1,36,1,152,1.10.2.20.3.15;");
    assert_eq!(
        AdvancedRandomTrigger::from_object(&obj)
            .unwrap()
            .probabilities,
        vec![(1, 10), (2, 20), (3, 15)]
    );
}

