#[test]
fn spinning_object_rotation_properties() {
    let props = |rotation| {
        SpinningObjectConfig {
            object: SpinningObject::LargeSawBlade,
            rotation,
        }
        .serialise()
    };
    assert!(props(RotationConfig::Default).is_empty());
    assert_eq!(
        props(RotationConfig::Custom(125)),
        vec![(p::CUSTOM_ROTATION_AMOUNT, GDValue::Int(125))]
    );
    assert_eq!(
        props(RotationConfig::Disabled),
        vec![(p::ROTATION_DISABLED, GDValue::Bool(true))]
    );
}

#[test]
fn spinning_object_from_real_strings() {
    // from the comment in `constructors/mod.rs`
    let parse = |s| {
        SpinningObjectConfig::from_object(&GDObject::parse_str(s))
            .unwrap()
            .rotation
    };
    assert_eq!(parse("1,1705,2,2505,3,315;"), RotationConfig::Default);
    assert_eq!(
        parse("1,1705,2,2505,3,315,97,125;"),
        RotationConfig::Custom(125)
    );
    assert_eq!(parse("1,1705,2,2505,3,315,98,1;"), RotationConfig::Disabled);
}

#[test]
fn move_trigger_mode_properties() {
    let props = |move_config| {
        MoveTrigger {
            move_config,
            time: 1.0,
            target_group: 1,
            silent: false,
            dynamic: false,
            easing: Easing::none(),
        }
        .serialise()
    };
    let has = |props: &[(u16, GDValue)], id: u16| props.iter().any(|(i, _)| *i == id);

    let default = props(MoveMode::Default(DefaultMove {
        dx: 1,
        dy: 2,
        x_lock: None,
        y_lock: None,
    }));
    assert!(default.contains(&(p::MOVE_UNITS_X, GDValue::Int(1))));
    assert!(default.contains(&(p::MOVE_UNITS_Y, GDValue::Int(2))));
    assert!(!has(&default, p::TARGET_MOVE_MODE));
    assert!(!has(&default, p::DIRECTIONAL_MOVE_MODE));

    let target = props(MoveMode::Targeting(TargetMove {
        target_group_id: MoveTarget::Group(5),
        center_group_id: None,
        axis_only: None,
    }));
    assert!(target.contains(&(p::TARGET_MOVE_MODE, GDValue::Bool(true))));
    assert!(target.contains(&(p::TARGET_ITEM_2, GDValue::Group(5))));
    assert!(!has(&target, p::MOVE_UNITS_X));

    let directional = props(MoveMode::Directional(DirectionalMove {
        target_group_id: MoveTarget::Player1,
        center_group_id: None,
        distance: 30,
    }));
    assert!(has(&directional, p::DIRECTIONAL_MOVE_MODE));
    assert!(has(&directional, p::CONTROLLING_PLAYER_1));
    assert!(directional.contains(&(p::DIRECTIONAL_MODE_DISTANCE, GDValue::Int(30))));
}

#[test]
fn counter_label_item_properties() {
    let props = |item| {
        CounterLabel {
            item,
            align: ItemAlign::Center,
            seconds_only: false,
        }
        .serialise()
    };
    let has = |props: &[(u16, GDValue)], id: u16| props.iter().any(|(i, _)| *i == id);

    let counter = props(Item::Counter(5));
    assert!(counter.contains(&(p::INPUT_ITEM_1, GDValue::Item(5))));
    assert!(!has(&counter, p::IS_TIMER));
    assert!(!has(&counter, p::SPECIAL_COUNTER_MODE));

    let timer = props(Item::Timer(3));
    assert!(timer.contains(&(p::INPUT_ITEM_1, GDValue::Item(3))));
    assert!(timer.contains(&(p::IS_TIMER, GDValue::Bool(true))));

    for (item, mode) in [
        (Item::Attempts, CounterMode::Attempts),
        (Item::Points, CounterMode::Points),
        (Item::MainTime, CounterMode::MainTime),
    ] {
        let special = props(item);
        assert!(
            special.contains(&(p::SPECIAL_COUNTER_MODE, GDValue::CounterMode(mode))),
            "{item:?}: {special:?}"
        );
    }
}

#[test]
fn gravity_trigger_target_player_properties() {
    for (player, id) in [
        (TargetPlayer::Player1, p::CONTROLLING_PLAYER_1),
        (TargetPlayer::Player2, p::CONTROLLING_PLAYER_2),
        (TargetPlayer::PlayerTarget, p::CONTROLLING_TARGET_PLAYER),
    ] {
        let props = GravityTrigger {
            gravity: 1.0,
            target_player: Some(player),
        }
        .serialise();
        assert!(props.contains(&(id, GDValue::Bool(true))), "{player:?}");
    }
    let props = GravityTrigger {
        gravity: 1.0,
        target_player: None,
    }
    .serialise();
    assert_eq!(props, vec![(p::GRAVITY, GDValue::Float(1.0))]);
}

#[test]
fn item_edit_trigger_without_operands_has_no_input_items() {
    let props = ItemEditTrigger {
        operand1: None,
        operand2: None,
        target: Item::Counter(1),
        modifier: 1.0,
        assign_op: Op::Set,
        multiply_mod: true,
        id_op: Op::Add,
        id_rounding: RoundMode::None,
        result_rounding: RoundMode::None,
        id_sign: SignMode::None,
        result_sign: SignMode::None,
    }
    .serialise();
    for id in [
        p::INPUT_ITEM_1,
        p::INPUT_ITEM_2,
        p::FIRST_ITEM_TYPE,
        p::SECOND_ITEM_TYPE,
    ] {
        assert!(!props.iter().any(|(i, _)| *i == id), "property {id}");
    }
}

