#[test]
fn animate_trigger_builtin_animation_becomes_other() {
    // documented on `AnimateTrigger.animation`
    let t = AnimateTrigger {
        target_group: 1,
        animation: Anim::Bat(animation_ids::Bat::Sleep),
    };
    let obj = GDObject::parse_str(
        GDObject::from_config(&GDObjConfig::default(), t).serialise_to_string(),
    );
    assert_eq!(
        AnimateTrigger::from_object(&obj).unwrap().animation,
        Anim::Other(animation_ids::Bat::Sleep as i32)
    );
}

